function validateField(field,isValid,message){const formGroup=field.closest(".form-group, .col-md-6, .col-md-4, .col-md-12");const feedbackElement=formGroup?formGroup.querySelector(".invalid-feedback"):null;if(isValid){field.classList.remove("is-invalid");field.classList.add("is-valid");if(feedbackElement){feedbackElement.style.display="none";}}else{field.classList.remove("is-valid");field.classList.add("is-invalid");if(feedbackElement){feedbackElement.textContent=message;feedbackElement.style.display="block";}else{const feedback=document.createElement("div");feedback.className="invalid-feedback d-block";feedback.textContent=message;field.parentNode.appendChild(feedback);}}
return isValid;}
function validateBusinessHours(startTimeField,endTimeField){const startTimeStr=startTimeField.value;const endTimeStr=endTimeField.value;if(!startTimeStr||!endTimeStr){return true;}
const timeRegex=/^\d{2}:\d{2}$/;if(!timeRegex.test(startTimeStr)||!timeRegex.test(endTimeStr)){validateField(startTimeField,false,"Invalid time format.");validateField(endTimeField,false,"Invalid time format.");return false;}
const[startHour,startMinute]=startTimeStr.split(":").map(Number);const[endHour,endMinute]=endTimeStr.split(":").map(Number);let startTotalMinutes=startHour*60+startMinute;let endTotalMinutes=endHour*60+endMinute;if(startHour<11)startTotalMinutes+=24*60;if(endHour<11)endTotalMinutes+=24*60;const businessStartMinutes=11*60;const businessEndMinutes=25*60;let isStartValid=startTotalMinutes>=businessStartMinutes&&startTotalMinutes<businessEndMinutes;let isEndValid=endTotalMinutes>businessStartMinutes&&endTotalMinutes<=businessEndMinutes;let isEndAfterStart=endTotalMinutes>startTotalMinutes;const startValid=validateField(startTimeField,isStartValid,"Start time must be between 11:00 AM and 12:30 AM.");const endValid=validateField(endTimeField,isEndValid&&isEndAfterStart,!isEndAfterStart?"End time must be after start time.":"End time must be between 11:30 AM and 1:00 AM.");return startValid&&endValid;}
function validateReservationForm(form){let isValid=true;const fieldsToValidate=[{id:"contact_name",required:true,message:"Please enter a contact name.",},{id:"contact_phone",required:true,message:"Please enter a contact phone number.",pattern:/^\+?[\d\s\-\(\)]{7,}$/,},{id:"contact_email",required:false,message:"Please enter a valid email address.",pattern:/^[^\s@]+@[^\s@]+\.[^\s@]+$/,},{id:"num_people",required:true,message:"Number of people must be 1 or more.",min:1,},{id:"room_id",required:true,message:"Please select a room."},{id:"start_time",required:true,message:"Please select a start time.",},{id:"end_time",required:true,message:"Please select an end time."},];fieldsToValidate.forEach((config)=>{const field=form.querySelector(`#${config.id}`);if(!field)return;let fieldValid=true;const value=field.value.trim();if(config.required&&value===""){fieldValid=false;validateField(field,false,config.message);}else if(config.pattern&&value!==""&&!config.pattern.test(value)){fieldValid=false;validateField(field,false,config.message);}else if(config.min!==undefined||config.max!==undefined){const numValue=parseInt(value);if(isNaN(numValue)||(config.min!==undefined&&numValue<config.min)||(config.max!==undefined&&numValue>config.max)){fieldValid=false;validateField(field,false,config.message);}else{validateField(field,true,"");}}else if(value!==""||config.required){validateField(field,true,"");}
isValid=isValid&&fieldValid;});const startTimeField=form.querySelector("#start_time");const endTimeField=form.querySelector("#end_time");if(startTimeField&&endTimeField&&startTimeField.value&&endTimeField.value){const timeValid=validateBusinessHours(startTimeField,endTimeField);isValid=isValid&&timeValid;}
return isValid;}
function clearFormValidation(form){const alert=form.querySelector("#form-error-alert");if(alert)alert.classList.add("d-none");form.querySelectorAll(".is-invalid, .is-valid").forEach((field)=>{field.classList.remove("is-invalid","is-valid");});form.querySelectorAll(".invalid-feedback").forEach((feedback)=>{feedback.style.display="none";});}
function handleReservationSubmit(event){event.preventDefault();event.stopPropagation();const form=event.target;const alertElement=form.querySelector("#form-error-alert");clearFormValidation(form);if(!validateReservationForm(form)){if(alertElement){alertElement.textContent="Please correct the errors highlighted below.";alertElement.classList.remove("d-none");}
const firstInvalidField=form.querySelector(".is-invalid");if(firstInvalidField){firstInvalidField.focus();}
return;}
const disabledFields=[];form.querySelectorAll(":disabled").forEach((field)=>{disabledFields.push(field);field.disabled=false;});const formData=new FormData(form);disabledFields.forEach((field)=>{field.disabled=true;});const jsonData={};formData.forEach((value,key)=>{jsonData[key]=value;});if(!jsonData.reservation_id){delete jsonData.reservation_id;}
const reservationId=jsonData["reservation_id"];let apiUrl=reservationId?`/api/reservations/${reservationId}`:"/api/reservations";let method=reservationId?"PATCH":"POST";if(window.currentRole==="customer"&&!reservationId){apiUrl="/api/requests";method="POST";}
const roomSelect=form.querySelector("#room_id");const idleSelected=roomSelect&&roomSelect.value==="idle";const modalEl=document.getElementById("reservationModal");const wasIdle=modalEl?.dataset?.inIdle==="true";if(idleSelected){const fallbackRoom=roomSelect?.querySelector('option[value]:not([value="idle"])');jsonData["room_id"]=fallbackRoom?fallbackRoom.value:"1";jsonData["idle"]=true;}
const submitButton=form.querySelector('button[type="submit"]');const originalText=submitButton.innerHTML;submitButton.disabled=true;submitButton.innerHTML='<span class="spinner-border spinner-border-sm" role="status" aria-hidden="true"></span> Saving...';fetch(apiUrl,{method:method,headers:{"Content-Type":"application/json",Accept:"application/json",},body:JSON.stringify(jsonData),}).then(async(response)=>{let responseData={};try{responseData=await response.json();}catch(err){}
if(!response.ok){const rawMessage=responseData?.message||responseData?.error||responseData?.detail||(response.status===409?"Room is not available for the selected time":null)||`Request failed with status ${response.status}`;const formattedMessage=typeof rawMessage==="object"?"Room is not available for the selected time":rawMessage;throw new Error(formattedMessage);}
return responseData;}).then((data)=>{window.showToast(data.message||"Reservation saved successfully!","success");const modalElement=document.getElementById("reservationModal");const modal=bootstrap.Modal.getInstance(modalElement);if(modal)modal.hide();const dateInput=document.getElementById("date");const date=(dateInput&&dateInput.value)||jsonData.date;const finalizeRefresh=()=>{if(typeof window.updateRoomTimelines==="function"&&date)
window.updateRoomTimelines(date);if(typeof window.updateIdleArea==="function")window.updateIdleArea();if(typeof window.refreshCalendarAvailability==="function")
window.refreshCalendarAvailability();if(typeof window.loadCustomerBookings==="function"&&window.currentRole==="customer"){window.loadCustomerBookings();}};if(idleSelected){if(data.reservation?.in_idle){finalizeRefresh();}else{fetch(`/move_to_idle/${data.reservation?.id || reservationId}`,{method:"POST",}).then(()=>finalizeRefresh()).catch(()=>finalizeRefresh());}}else if(wasIdle){fetch(`/remove_from_idle/${data.reservation?.id || reservationId}`,{method:"POST",}).then(()=>finalizeRefresh()).catch(()=>finalizeRefresh());}else{finalizeRefresh();}}).catch((error)=>{console.error("Error saving reservation:",error);if(alertElement){alertElement.textContent=error.message||"An unexpected error occurred. Please try again.";alertElement.classList.remove("d-none");}
window.showToast(error.message||"Failed to save reservation.","error");if(error.message&&error.message.includes("time slot is already occupied")){validateField(form.querySelector("#start_time"),false,"Time conflict.");validateField(form.querySelector("#end_time"),false,"Time conflict.");validateField(form.querySelector("#room_id"),false,"Room unavailable at this time.");}
if(error.message&&error.message.includes("business hours")){validateField(form.querySelector("#start_time"),false,"Outside business hours.");validateField(form.querySelector("#end_time"),false,"Outside business hours.");}}).finally(()=>{submitButton.disabled=false;submitButton.innerHTML=originalText;});}
document.addEventListener("DOMContentLoaded",function(){const reservationForm=document.getElementById("reservationForm");if(reservationForm){reservationForm.querySelectorAll("input, select, textarea").forEach((field)=>{field.addEventListener("input",()=>{if(field.id==="start_time"||field.id==="end_time"){const startField=reservationForm.querySelector("#start_time");const endField=reservationForm.querySelector("#end_time");if(startField.value&&endField.value){validateBusinessHours(startField,endField);}}else{if(field.hasAttribute("required")){validateField(field,field.value.trim()!=="",field.closest(".form-group")?.querySelector("label")?.textContent+" is required.");}}});});reservationForm.addEventListener("submit",handleReservationSubmit);}});